+          ..throwOnPath = '/home/u/.fah/config.yaml';
+        final (submit, cli) = await openIncidentFlow(throwingEnv: throwingEnv);
+        await cli.tuiWizardPickForTest('wizard:maxTokens in tokens', '65536');
