/// The index after the last line of the block body under the key line at
/// [keyLine] (indent [depth]); blank lines inside the block are consumed,
/// a blank line separating it from the next section is kept.
int _blockEnd(List<String> lines, int keyLine, int depth) {
  var end = keyLine + 1;
  while (end < lines.length) {
    final line = lines[end];
    if (_indentOf(line) > depth * 2) {
      end++;
      continue;
    }
    if (line.trim().isEmpty) {
      final next = end + 1 < lines.length ? lines[end + 1] : '';
      if (next.isEmpty || _indentOf(next) > depth * 2) {
        end++;
        continue;
      }
    }
    break;
  }
  return end;
}

/// The leaf value lines for a config value: a JSON array/object renders
/// as a yaml block under the key (list-valued keys — `customProviders`,
/// the `roles:` chains, `redact:` lists); anything else stays the single
/// scalar line `renderYamlScalar` always wrote. Shared by `config set`
/// and the settings flows' surgical upsert.
List<String> configLeafLines(String value, {required int depth}) {
  final raw = value.trim();
  if (!raw.startsWith('[') && !raw.startsWith('{')) {
    return [renderYamlScalar(value)];
  }
  final Object? decoded;
  try {
    decoded = jsonDecode(raw);
  } on FormatException {
